import{z as s,x as l,o as e,c as d,q as t,j as B,D as E,d as r,s as i,S as A,b as n}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"结构模型的验证","description":"","frontmatter":{"title":"结构模型的验证","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/se-validation.md","filePath":"econ/se-validation.md","lastUpdated":1791063341000}'),p={name:"econ/se-validation.md"};function c(m,a,h,D,f,C){const o=l("Mermaid");return e(),d("div",null,[a[2]||(a[2]=t('<h1 id="结构模型的验证" tabindex="-1">结构模型的验证 <a class="header-anchor" href="#结构模型的验证" aria-label="Permalink to &quot;结构模型的验证&quot;">​</a></h1><div class="epigraph"><p>拟合得再好的矩也不背书反事实；验证的对象是不变性——换市场、换年份、换政策，估好的参数是否还在原处。</p><footer>—— 据 Berry, Levinsohn and Pakes, Econometrica 1995；Peters, Evaluating the Performance of Merger Simulation, JLEO 2006 整理</footer></div><p><a href="/econ/se-smm">上一课</a>把积分与模拟误差管住，至此估计与计算都有答案。还欠一件事：这些参数只是拟合了你选定的矩，反事实是模型在从未发生过的区域的输出。<a href="/econ/structural-vs-reduced">结构对约化形式</a>主干课立了口令——结构的价值在不变形的参数；本课写「不变形」怎么被检验。合并模拟的实绩评估是最好的试验场：模型预测的合并涨价，与事后真实涨价比。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>验证的困难是结构性的：反事实的支持里没有数据，以后也不会有。能做的是把不变性拆成可检验的分段——跨市场的（同一需求在别的城市成立吗）、跨时间的（昨天的偏好在今年还稳吗）、跨政策的（行为对规则变化的反应被钉住了吗）。拟合优度不回答这些：\\(J\\) 不拒绝只说明矩彼此一致（<a href="/econ/gmm-econ">GMM</a> 课的旧话），观测等价的模型可以在支持外给出完全不同的反事实。缺口是操作协议：哪些检验、什么顺序、失败后怎么办。</p><p><span class="marginnote">术语翻译：「不变性」就是「参数是世界的性质，不是这次回归的副产物」——换城市、换年份、换政策，同一套偏好与成本还该适用。反事实的全部信用都押在这句话上，所以验证就是系统地给这句话找麻烦。</span></p><h3 id="验证协议" tabindex="-1">验证协议 <a class="header-anchor" href="#验证协议" aria-label="Permalink to &quot;验证协议&quot;">​</a></h3><p>四层。第一层，样本外预测：留出市场或年份，用估好的模型预测价格、份额、新品份额，预测误差与估计期拟合直接对比。第二层，约束复现：供给一阶条件在观测所有权下应能复现观测价格（<a href="/econ/merger-simulation">合并模拟</a>课的检验步骤），失败即结构有缝。第三层，伪反事实：模型预测一个「其实发生过」的事件（已实施的政策、已完成的合并），与<a href="/econ/difference-in-differences">双重差分</a>或<a href="/econ/rdd">断点回归</a>的准实验估计对表——同一事件、两种口径。第四层，敏感性与不确定性：换工具、换分布假设、换市场定义重估；反事实区间用<a href="/econ/bootstrap-econ">自举</a>或后验给出，不报裸点。</p><p><span class="marginnote">Peters 2006 把模拟预测与事后价格对照：需求弹性与方法的选择都会改变预测方向。单一案例的胜负不裁决模型，系统性对照才暴露「拟合好、反事实差」的组合；验证段要报负面结果，不能只留通过项。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>顺序即纪律：先检验后使用。留出集必须在估计前冻结，否则「样本外」只是同一样本的二次拟合。伪反事实要对表同事件：模型预测的是「若当时涨价一成」，DiD 估的是实际发生的那个事件，口径不一致的比较是修辞。不确定性分两条传：参数不确定性（自举或后验）与均衡解的数值误差分开报。失败后的选项按诚实度排：改结构（换替代模式、加状态）、收窄适用域、转部分识别报界——顺序不能倒，把界悄悄换成点估计等于没验。</p><p><span class="marginnote">直觉类比：留出集像考卷——必须在你答题之前封存。若先看过考卷再调模型，再高的分数也只是背过答案；「样本外预测」只有从估计那一刻起就没看见过的数据，才算数。</span></p>',12)),(e(),B(A,null,{default:E(()=>[i(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20EST%5B%22%E4%BC%B0%E5%A5%BD%E7%9A%84%E7%BB%93%E6%9E%84%E5%8F%82%E6%95%B0%22%5D%20--%3E%20OOS%5B%22%E5%86%BB%E7%BB%93%E7%95%99%E5%87%BA%3A%20%E6%A0%B7%E6%9C%AC%E5%A4%96%E9%A2%84%E6%B5%8B%22%5D%0A%20%20EST%20--%3E%20FOC%5B%22%E4%B8%80%E9%98%B6%E6%9D%A1%E4%BB%B6%E5%A4%8D%E7%8E%B0%E8%A7%82%E6%B5%8B%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20EST%20--%3E%20PC%5B%22%E4%BC%AA%E5%8F%8D%E4%BA%8B%E5%AE%9E%20vs%20%E5%87%86%E5%AE%9E%E9%AA%8C%22%5D%0A%20%20OOS%20--%3E%20SENS%5B%22%E6%8D%A2%E5%B7%A5%E5%85%B7%20%2F%20%E5%88%86%E5%B8%83%20%2F%20%E5%B8%82%E5%9C%BA%E5%AE%9A%E4%B9%89%22%5D%0A%20%20FOC%20--%3E%20SENS%0A%20%20PC%20--%3E%20SENS%0A%20%20SENS%20--%3E%20REP%5B%22%E6%8A%A5%E5%91%8A%3A%20%E5%8C%BA%E9%97%B4%E4%B8%8E%E9%80%82%E7%94%A8%E5%9F%9F%2C%20%E6%88%96%E6%94%B9%E7%BB%93%E6%9E%84%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[r("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"机制是「验什么」。每个检验对应一段不变性声明：样本外预测验市场间不变，一阶条件复现验成本与行为假设，伪反事实验政策反应函数，敏感性验结论对不可检验假设的依赖。模型可以层层通过而仍在新政策上错——政策若改变模型未建模的边际（进入、产品重定位、合谋组织），那是结构的边界而非验证的失败，但要写出来。验证的产出不是「通过或不通过」，是「模型在哪些区域可信」的地图。",-1)),(e(),B(A,null,{default:E(()=>[i(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAIL%5B%22%E6%9F%90%E4%B8%80%E5%B1%82%E9%AA%8C%E8%AF%81%E5%A4%B1%E8%B4%A5%22%5D%20--%3E%20Q1%7B%22%E6%8D%A2%E7%BB%93%E6%9E%84%E8%83%BD%E4%BF%AE%E5%A4%8D%E5%90%97%22%7D%0A%20%20Q1%20--%3E%7C%22%E8%83%BD%22%7C%20FIX%5B%22%E6%94%B9%E7%BB%93%E6%9E%84%EF%BC%9A%E6%8D%A2%E6%9B%BF%E4%BB%A3%E6%A8%A1%E5%BC%8F%E6%88%96%E5%8A%A0%E7%8A%B6%E6%80%81%22%5D%0A%20%20Q1%20--%3E%7C%22%E4%B8%8D%E8%83%BD%22%7C%20Q2%7B%22%E5%A4%B1%E8%B4%A5%E5%8F%AA%E9%99%90%E4%BA%8E%E9%83%A8%E5%88%86%E5%8C%BA%E5%9F%9F%E5%90%97%22%7D%0A%20%20Q2%20--%3E%7C%22%E6%98%AF%22%7C%20NAR%5B%22%E6%94%B6%E7%AA%84%E9%80%82%E7%94%A8%E5%9F%9F%E5%B9%B6%E5%86%99%E6%98%8E%22%5D%0A%20%20Q2%20--%3E%7C%22%E5%90%A6%22%7C%20BND%5B%22%E8%BD%AC%E9%83%A8%E5%88%86%E8%AF%86%E5%88%AB%2C%20%E6%8A%A5%E7%95%8C%E4%B8%8D%E6%8A%A5%E7%82%B9%22%5D%0A%20%20FIX%20--%3E%20RE%5B%22%E9%87%8D%E6%96%B0%E8%BF%87%E4%B8%80%E9%81%8D%E5%9B%9B%E5%B1%82%E5%8D%8F%E8%AE%AE%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">常见误区：初学者容易把「矩拟合得好、\\(J\\) 检验不拒绝」当成模型通过了验证。那只说明你选的矩彼此自洽；两个观测上等价的模型，可以在数据没覆盖的区域给出方向相反的反事实。验证的对象是不变性，不是拟合。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>验证不产生证明：通过全部检验也不担保下一场干预。校准拟合不是验证（<a href="/econ/calibration-moments">校准与矩匹配</a>的旧分别）。微观验证（二次选择、购买面板）是额外证据，不是豁免。伪反事实里准实验自身也有识别假设，对表时两边都要摆出假设账。</p><p>后课默认：结构论文的验证段报四层协议的结果与失败处理；没有验证段的结构估计是命题，不是证据。下一课收束：把七课装置放回案例，看它们各自回答过什么问题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>拟合优度不验证反事实，验证对象是不变性的分段。</li><li>四层协议：样本外预测、约束复现、伪反事实对表准实验、敏感性加区间。</li><li>留出集估计前冻结，对表要同事件同口径。</li><li>失败后按诚实度处理：改结构、收窄域、报界，不得倒序。</li><li>出处：Berry, Levinsohn and Pakes, <em>Econometrica</em> 1995；Peters, <em>JLEO</em> 2006；准实验对照见 DiD 与 RDD 文献。</li></ul>',6))])}const _=s(p,[["render",c]]);export{F as __pageData,_ as default};
